on:
    workflow_dispatch:
        inputs:
            test:
                description: 'Optional: Title of test to run'
                required: false
                default: ''
jobs:
    test_schedule:
        runs-on: [self-hosted]
        steps:
            - name: Every time
              run: echo "This step will always run"
            - uses: actions/checkout@v3
            - name: Setup Node
